      friend: '다정하고 눈치가 빨라 누구와도 잘 어울립니다. 싫은 소리를 잘 못해서 속으로 서운함을 쌓을 수 있어요.',
      love: '세심하게 챙기고 맞춰 주는 연애를 합니다. 기대고 싶은 마음도 커서 애정 표현을 자주 받고 싶어 해요.',
