      friend: '말수는 적어도 언제나 그 자리에 있는 친구입니다. 고민을 들어주고 중심을 잡아 주는 역할을 해요.',
      love: '느리지만 깊고 안정적인 연애를 합니다. 화려한 이벤트보다 변함없는 신뢰로 사랑을 표현해요.',
