      friend: '의리를 목숨처럼 여기는 친구입니다. 내 편이면 끝까지 지키지만, 배신에는 단호해요.',
      love: '말보다 행동으로 사랑을 보여 줍니다. 표현이 투박해 오해를 사기도 하지만, 한번 정하면 확실해요.',
