      friend: '발이 넓고 어떤 사람이든 품어 주는 친구입니다. 다만 관심사가 많아 연락이 들쭉날쭉할 수 있어요.',
      love: '자유롭고 포용력 있는 연애를 합니다. 구속받는 것을 힘들어해서 서로의 공간을 존중하는 관계가 잘 맞아요.',
